<template>
  <section class="auto-panel">
    <header><div><h3>Tự động trả lời</h3><p>Cấu hình theo lộ trình an toàn: tắt → chạy mô phỏng → tự gửi có kiểm soát.</p></div><span class="state-pill" :class="form.emergencyStop?'stopped':form.mode">{{ stateLabel }}</span></header>
    <div v-if="error" class="notice error">{{ error }}</div><div v-if="success" class="notice success">{{ success }}</div>
    <div v-if="loading" class="notice">Đang tải cấu hình…</div>
    <template v-else>
      <section class="safety-card" :class="{danger:form.emergencyStop}"><span class="mdi" :class="form.emergencyStop?'mdi-stop-circle-outline':'mdi-shield-check-outline'"/><div><strong>{{ form.emergencyStop?'Emergency Stop đang bật':'Hệ thống chưa bị dừng khẩn cấp' }}</strong><p>Emergency Stop luôn có quyền ưu tiên cao nhất và chặn toàn bộ thao tác tự gửi.</p></div><label class="switch"><input v-model="form.emergencyStop" type="checkbox"/><span/></label></section>
      <div class="mode-grid">
        <label :class="{selected:form.mode==='disabled'}"><input v-model="form.mode" type="radio" value="disabled"/><span class="mdi mdi-power"/><strong>Tắt</strong><small>Không đánh giá hay tự gửi.</small></label>
        <label :class="{selected:form.mode==='shadow'}"><input v-model="form.mode" type="radio" value="shadow"/><span class="mdi mdi-eye-outline"/><strong>Mô phỏng</strong><small>Chạy điều kiện nhưng không gửi tin.</small></label>
        <label :class="{selected:form.mode==='auto_send'}"><input v-model="form.mode" type="radio" value="auto_send"/><span class="mdi mdi-send-check-outline"/><strong>Tự gửi</strong><small>Chỉ gửi khi toàn bộ cổng an toàn đạt.</small></label>
      </div>
      <section class="settings">
        <div class="section-head"><div><h4>Phạm vi Workspace</h4><p>Áp dụng cho toàn tổ chức; cấu hình cụ thể hơn có thể ghi đè theo tài khoản, kỹ năng hoặc intent.</p></div><label class="switch"><input v-model="form.enabled" type="checkbox"/><span/></label></div>
        <div class="form-grid">
          <label>Ngưỡng tin cậy (%)<input v-model.number="form.confidenceThreshold" type="number" min="50" max="100"/></label>
          <label>Tỷ lệ Canary (%)<input v-model.number="form.canaryPercent" type="number" min="0" max="100"/></label>
          <label>Giới hạn/ngày<input v-model.number="form.maxDaily" type="number" min="1" max="10000"/></label>
          <label>Giới hạn/hội thoại<input v-model.number="form.maxPerConversation" type="number" min="1" max="100"/></label>
          <label class="wide">Intent được phép<input v-model="form.allowedIntents" placeholder="product_inquiry, faq, greeting"/><small>Phân tách bằng dấu phẩy. Khi để trống, Auto Reply sẽ không tự gửi.</small></label>
          <label class="wide">Khung giờ hoạt động<div class="hour-row"><input v-model.number="form.startHour" type="number" min="0" max="23"/><span>đến</span><input v-model.number="form.endHour" type="number" min="0" max="23"/></div></label>
        </div>
      </section>
      <section class="gates"><h4>Các cổng bắt buộc trước khi tự gửi</h4><ul><li><span class="mdi mdi-check"/>Có Release Production đã vượt Evaluation</li><li><span class="mdi mdi-check"/>Có citation từ kho tri thức đã Publish</li><li><span class="mdi mdi-check"/>Policy cho phép và không yêu cầu nhân viên</li><li><span class="mdi mdi-check"/>Không phải hội thoại riêng tư bị khóa</li><li><span class="mdi mdi-check"/>Đạt ngưỡng tin cậy, phạm vi và hạn mức</li></ul></section>
      <footer><p>Chế độ Agent “Gợi ý” chỉ tạo nội dung cho nhân viên; chế độ Workspace “Tự gửi” mới có quyền gửi khi vượt toàn bộ cổng.</p><button :disabled="saving" @click="save"><span class="mdi mdi-content-save-outline"/>{{ saving?'Đang lưu…':'Lưu cấu hình' }}</button></footer>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';import { api } from '@/api/index';
type Row={id:string;scope:string;enabled:boolean;mode:string;emergencyStop:boolean;config:Record<string,any>;updatedAt:string};
const loading=ref(false),saving=ref(false),error=ref(''),success=ref('');const form=reactive({enabled:false,mode:'disabled',emergencyStop:true,confidenceThreshold:90,canaryPercent:0,maxDaily:100,maxPerConversation:3,allowedIntents:'',startHour:8,endHour:21});
const stateLabel=computed(()=>form.emergencyStop?'Đã dừng khẩn cấp':!form.enabled||form.mode==='disabled'?'Đang tắt':form.mode==='shadow'?'Đang mô phỏng':'Sẵn sàng tự gửi');
function apply(row?:Row){if(!row)return;const c=row.config||{};form.enabled=row.enabled;form.mode=row.mode;form.emergencyStop=row.emergencyStop;form.confidenceThreshold=Number(c.confidenceThreshold??90);form.canaryPercent=Number(c.canaryPercent??0);form.maxDaily=Number(c.maxDaily??100);form.maxPerConversation=Number(c.maxPerConversation??3);form.allowedIntents=Array.isArray(c.allowedIntents)?c.allowedIntents.join(', '):'';const hours=Array.isArray(c.activeHours)?c.activeHours[0]:null;form.startHour=Number(hours?.start??8);form.endHour=Number(hours?.end??21)}
async function load(){loading.value=true;error.value='';try{const rows=(await api.get<{configs:Row[]}>('/ai/auto-reply/config')).data.configs||[];apply(rows.find(item=>item.scope==='workspace'))}catch(e:any){error.value=e?.response?.data?.error||'Không thể tải cấu hình Auto Reply'}finally{loading.value=false}}
async function save(){if(form.mode==='auto_send'&&(!form.emergencyStop||form.enabled)){if(!window.confirm('Bạn đang cấu hình chế độ tự gửi. Hệ thống chỉ gửi khi có Release Production và vượt toàn bộ cổng an toàn. Tiếp tục lưu?'))return}saving.value=true;error.value='';success.value='';try{await api.put('/ai/auto-reply/config',{scope:'workspace',enabled:form.enabled,mode:form.mode,emergencyStop:form.emergencyStop,config:{confidenceThreshold:Math.max(50,Math.min(100,form.confidenceThreshold)),canaryPercent:Math.max(0,Math.min(100,form.canaryPercent)),maxDaily:Math.max(1,form.maxDaily),maxPerConversation:Math.max(1,form.maxPerConversation),allowedIntents:form.allowedIntents.split(',').map(v=>v.trim()).filter(Boolean),activeHours:[{start:Math.max(0,Math.min(23,form.startHour)),end:Math.max(0,Math.min(23,form.endHour))}]}});success.value='Đã lưu cấu hình Auto Reply.';await load()}catch(e:any){error.value=e?.response?.data?.error||'Không thể lưu cấu hình'}finally{saving.value=false}}onMounted(load);
</script>
<style scoped>
.auto-panel{display:grid;gap:16px}.auto-panel>header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.auto-panel h3{margin:0;font-size:20px;color:#172033}.auto-panel header p,.section-head p{margin:5px 0 0;color:#64748b;line-height:1.5}.state-pill{padding:6px 10px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:750}.state-pill.shadow{background:#dbeafe;color:#1d4ed8}.state-pill.auto_send{background:#dcfce7;color:#166534}.state-pill.stopped{background:#fee2e2;color:#991b1b}.notice{padding:12px;border-radius:8px;background:#f8fafc;color:#475569}.notice.error{background:#fff1f2;color:#991b1b}.notice.success{background:#ecfdf5;color:#166534}.safety-card{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:12px;padding:15px;border:1px solid #bbf7d0;border-radius:10px;background:#f0fdf4;color:#166534}.safety-card.danger{border-color:#fecaca;background:#fff1f2;color:#991b1b}.safety-card>.mdi{font-size:28px}.safety-card p{margin:4px 0 0}.switch input{position:absolute;opacity:0}.switch span{display:block;width:44px;height:24px;padding:3px;border-radius:999px;background:#cbd5e1;cursor:pointer}.switch span:after{display:block;width:18px;height:18px;border-radius:50%;background:#fff;box-shadow:0 1px 2px #0002;content:'';transition:.18s}.switch input:checked+span{background:#2563eb}.switch input:checked+span:after{transform:translateX(20px)}.mode-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.mode-grid label{display:grid;grid-template-columns:auto 1fr;gap:5px 10px;padding:14px;border:1px solid #dbe4f0;border-radius:10px;cursor:pointer}.mode-grid label.selected{border-color:#2563eb;background:#eff6ff}.mode-grid input{grid-row:1/4}.mode-grid .mdi{font-size:20px;color:#2563eb}.mode-grid small{grid-column:2;color:#64748b;line-height:1.4}.settings,.gates{padding:16px;border:1px solid #e2e8f0;border-radius:10px;background:#fff}.section-head{display:flex;justify-content:space-between;gap:14px}.section-head h4,.gates h4{margin:0;color:#172033}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:16px}.form-grid label{display:grid;gap:6px;color:#475569;font-weight:650}.form-grid input{min-height:39px;border:1px solid #cbd5e1;border-radius:7px;padding:8px 10px}.form-grid small{color:#64748b;font-weight:400}.form-grid .wide{grid-column:span 2}.hour-row{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:8px}.gates ul{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:13px 0 0;padding:0;list-style:none}.gates li{display:flex;gap:7px;color:#334155}.gates li .mdi{color:#16a34a}.auto-panel footer{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:13px 15px;border-radius:10px;background:#f8fafc}.auto-panel footer p{max-width:760px;margin:0;color:#64748b;line-height:1.5}.auto-panel footer button{border:1px solid #2563eb;border-radius:8px;background:#2563eb;color:#fff;padding:10px 14px;cursor:pointer;white-space:nowrap}@media(max-width:900px){.form-grid{grid-template-columns:1fr 1fr}.mode-grid{grid-template-columns:1fr}.gates ul{grid-template-columns:1fr}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.auto-panel footer{align-items:stretch;flex-direction:column}}
</style>
